{"file_path":"src/cli.js","content":"#!/usr/bin/env node
/**
 * The command. `node src/cli.js json` prints the configuration document read
 * from standard input as canonical JSON, and `node src/cli.js keys` prints the
 * path and type of every node in it.
 */

import * as fs from 'fs'
import * as readline from 'readline'

const args = process.argv.slice(2)

if (args.length !== 1 || !['json', 'keys'].includes(args[0])) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}

const mode = args[0]

// Read all input from stdin
const rl = readline.createInterface({
  input: process.stdin,
  output: undefined,
  terminal: false
})

let input = ''

rl.on('line', (line) => {
  input += line + '\n'
})

rl.on('close', () => {
  try {
    const doc = parseToml(input, mode)
    if (mode === 'json') {
      process.stdout.write(toJSON(doc) + '\n')
    } else {
      process.stdout.write(toKeys(doc))
    }
    process.exit(0)
  } catch (error) {
    process.stderr.write(error.message + '\n')
    process.exit(2)
  }
})

// Tokenizer/Parser
class Parser {
  constructor(input) {
    this.input = input
    this.pos = 0
    this.line = 1
    this.lines = input.split('\n').slice(0, -1) // Remove empty tail from trailing newline
    this.currentTable = null
    this.root = {}
  }

  error(msg) {
    throw new Error(`error: line ${this.line}: ${msg}`)
  }

  parse() {
    this.currentTable = this.root

    for (let i = 0; i < this.lines.length; i++) {
      this.line = i + 1
      const line = this.lines[i]
      const trimmed = line.trimStart()

      // Skip empty lines and comments
      if (trimmed === '' || trimmed[0] === '#' || trimmed[0] === ';') {
        continue
      }

      // Header line
      if (trimmed[0] === '[') {
        if (trimmed[1] === '[') {
          // Array of tables: [[name]]
          const match = trimmed.match(/^\[\[([^\]]*)\]\](.*)$/)
          if (!match) {
            this.error('unterminated table header')
          }
          const nameStr = match[1].trim()
          const trailing = match[2]
          if (!/^\s*(#|;|$)/.test(trailing)) {
            this.error('trailing text after a table header')
          }
          const name = this.parseDottedName(nameStr)
          this.handleArrayTableHeader(name)
        } else {
          // Regular table: [name]
          const match = trimmed.match(/^\[([^\]]*)\](.*)$/)
          if (!match) {
            this.error('unterminated table header')
          }
          const nameStr = match[1].trim()
          const trailing = match[2]
          if (!/^\s*(#|;|$)/.test(trailing)) {
            this.error('trailing text after a table header')
          }
          const name = this.parseDottedName(nameStr)
          this.handleTableHeader(name)
        }
      } else {
        // Key-value pair
        this.parseKeyValue(trimmed)
      }
    }

    return this.root
  }

  parseDottedName(str) {
    if (str === '') {
      this.error('expected a name')
    }
    const parts = []
    let pos = 0
    while (pos < str.length) {
      // Skip whitespace
      while (pos < str.length && (str[pos] === ' ' || str[pos] === '\t')) {
        pos++
      }
      if (pos >= str.length) break

      // Parse name
      let name
      if (str[pos] === '"' || str[pos] === "'") {
        const quote = str[pos]
        pos++
        let name_str = ''
        while (pos < str.length) {
          if (str[pos] === quote) {
            pos++
            name = name_str
            break
          } else if (quote === '"' && str[pos] === '\\') {
            pos++
            if (pos >= str.length) {
              this.error('unterminated string')
            }
            const char = str[pos]
            if (char === 'n') name_str += '\n'
            else if (char === 't') name_str += '\t'
            else if (char === 'r') name_str += '\r'
            else if (char === '\\') name_str += '\\'
            else if (char === '"') name_str += '"'
            else if (char === '0') name_str += '\0'
            else if (char === 'u') {
              pos++
              if (pos + 3 >= str.length) {
                this.error('invalid escape \\u')
              }
              const hex = str.substr(pos, 4)
              if (!/^[0-9a-fA-F]{4}$/.test(hex)) {
                this.error('invalid escape \\u')
              }
              name_str += String.fromCharCode(parseInt(hex, 16))
              pos += 3
            } else {
              this.error(`invalid escape \\${char}`)
            }
            pos++
          } else {
            name_str += str[pos]
            pos++
          }
        }
        if (name === undefined) {
          this.error('unterminated string')
        }
      } else {
        let name_str = ''
        while (pos < str.length && /[A-Za-z0-9_-]/.test(str[pos])) {
          name_str += str[pos]
          pos++
        }
        if (name_str === '') {
          this.error('expected a name')
        }
        name = name_str
      }
      parts.push(name)

      // Skip whitespace
      while (pos < str.length && (str[pos] === ' ' || str[pos] === '\t')) {
        pos++
      }

      // Check for dot
      if (pos < str.length && str[pos] === '.') {
        pos++
      } else if (pos < str.length) {
        this.error('expected a name')
      }
    }

    if (parts.length === 0) {
      this.error('expected a name')
    }
    return parts
  }

  handleTableHeader(name) {
    let table = this.root
    const path = []

    for (let i = 0; i < name.length; i++) {
      const key = name[i]
      path.push(key)
      const pathStr = path.join('.')

      if (table[key] === undefined) {
        table[key] = {}
      } else if (typeof table[key] === 'object' && !Array.isArray(table[key])) {
        // It's already a table, that's fine
        table = table[key]
        continue
      } else {
        // It's something else
        this.error(`${pathStr} is not a table`)
      }

      table = table[key]
    }

    // Check if this exact table was already explicitly defined
    if (table._defined) {
      this.error(`table ${name.join('.')} is defined twice`)
    }
    table._defined = true
    this.currentTable = table
  }

  handleArrayTableHeader(name) {
    let table = this.root
    const path = []

    for (let i = 0; i < name.length - 1; i++) {
      const key = name[i]
      path.push(key)
      const pathStr = path.join('.')

      if (table[key] === undefined) {
        table[key] = {}
      } else if (typeof table[key] === 'object' && !Array.isArray(table[key])) {
        table = table[key]
        continue
      } else {
        this.error(`${pathStr} is not a table`)
      }

      table = table[key]
    }

    const lastKey = name[name.length - 1]
    path.push(lastKey)

    if (table[lastKey] === undefined) {
      table[lastKey] = []
    } else if (!Array.isArray(table[lastKey])) {
      this.error(`${path.join('.')} is not an array of tables`)
    }

    const newTable = {}
    table[lastKey].push(newTable)
    this.currentTable = newTable
  }

  parseKeyValue(line) {
    // Find the equals sign (outside of strings)
    let eqPos = -1
    let inString = false
    let stringChar = ''
    let i = 0

    while (i < line.length) {
      const char = line[i]
      if (!inString) {
        if (char === '"' || char === "'") {
          inString = true
          stringChar = char
        } else if (char === '=') {
          eqPos = i
          break
        } else if (char === '#' || char === ';') {
          // End of line
          break
        }
      } else {
        if (char === stringChar && (stringChar === "'" || line[i - 1] !== '\\')) {
          inString = false
        } else if (char === '\\' && stringChar === '"') {
          i++ // Skip escaped char
        }
      }
      i++
    }

    if (eqPos === -1) {
      this.error('expected key = value')
    }

    const keyPart = line.substring(0, eqPos).trim()
    const valuePart = line.substring(eqPos + 1)

    const key = this.parseDottedName(keyPart)
    const value = this.parseValue(valuePart)

    // Navigate/create the path
    let table = this.currentTable
    const path = []

    for (let i = 0; i < key.length - 1; i++) {
      const k = key[i]
      path.push(k)

      if (table[k] === undefined) {
        table[k] = {}
      } else if (typeof table[k] === 'object' && !Array.isArray(table[k])) {
        table = table[k]
        continue
      } else {
        this.error(`${path.join('.')} is not a table`)
      }

      table = table[k]
    }

    const lastKey = key[key.length - 1]
    path.push(lastKey)

    if (table[lastKey] !== undefined) {
      this.error(`key ${path.join('.')} is defined twice`)
    }

    table[lastKey] = value
  }

  parseValue(str) {
    str = str.trimStart()

    if (str === '') {
      this.error('expected a value')
    }

    // Boolean
    if (str.startsWith('true')) {
      const rest = str.substring(4)
      if (!this.isEndOfValue(rest)) {
        this.error('trailing text after a value')
      }
      return true
    }
    if (str.startsWith('false')) {
      const rest = str.substring(5)
      if (!this.isEndOfValue(rest)) {
        this.error('trailing text after a value')
      }
      return false
    }

    // String
    if (str[0] === '"') {
      return this.parseBasicString(str)
    }
    if (str[0] === "'") {
      return this.parseLiteralString(str)
    }

    // Array
    if (str[0] === '[') {
      return this.parseArray(str)
    }

    // Inline table
    if (str[0] === '{') {
      return this.parseInlineTable(str)
    }

    // Number or invalid
    let numStr = ''
    let hasDecimal = false
    let hasExponent = false
    let i = 0

    // Optional sign
    if (str[i] === '+' || str[i] === '-') {
      numStr += str[i]
      i++
    }

    // Digits and underscores
    let seenDigit = false
    while (i < str.length) {
      if (/[0-9]/.test(str[i])) {
        numStr += str[i]
        seenDigit = true
        i++
      } else if (str[i] === '_') {
        i++
        if (i >= str.length || !/[0-9]/.test(str[i])) {
          this.error(`invalid value ${str.substring(0, i)}`)
        }
        numStr += str[i]
        i++
      } else {
        break
      }
    }

    if (!seenDigit) {
      this.error(`invalid value ${str.substring(0, Math.min(i + 1, str.length))}`)
    }

    // Decimal part
    if (i < str.length && str[i] === '.') {
      hasDecimal = true
      numStr += '.'
      i++
      if (i >= str.length || !/[0-9]/.test(str[i])) {
        this.error(`invalid value ${numStr}`)
      }
      while (i < str.length) {
        if (/[0-9]/.test(str[i])) {
          numStr += str[i]
          i++
        } else if (str[i] === '_') {
          i++
          if (i >= str.length || !/[0-9]/.test(str[i])) {
            this.error(`invalid value ${numStr}`)
          }
          numStr += str[i]
          i++
        } else {
          break
        }
      }
    }

    // Exponent part
    if (i < str.length && (str[i] === 'e' || str[i] === 'E')) {
      hasExponent = true
      numStr += str[i]
      i++
      if (i < str.length && (str[i] === '+' || str[i] === '-')) {
        numStr += str[i]
        i++
      }
      if (i >= str.length || !/[0-9]/.test(str[i])) {
        this.error(`invalid value ${numStr}`)
      }
      while (i < str.length) {
        if (/[0-9]/.test(str[i])) {
          numStr += str[i]
          i++
        } else if (str[i] === '_') {
          i++
          if (i >= str.length || !/[0-9]/.test(str[i])) {
            this.error(`invalid value ${numStr}`)
          }
          numStr += str[i]
          i++
        } else {
          break
        }
      }
    }

    const rest = str.substring(i)
    if (!this.isEndOfValue(rest)) {
      this.error('trailing text after a value')
    }

    if (hasDecimal || hasExponent) {
      return parseFloat(numStr)
    } else {
      return parseInt(numStr, 10)
    }
  }

  isEndOfValue(str) {
    str = str.trimStart()
    return str === '' || str[0] === '#' || str[0] === ';'
  }

  parseBasicString(str) {
    if (!str.startsWith('"')) {
      this.error('expected a string')
    }

    let result = ''
    let i = 1

    while (i < str.length) {
      const char = str[i]
      if (char === '"') {
        const rest = str.substring(i + 1)
        if (!this.isEndOfValue(rest)) {
          this.error('trailing text after a value')
        }
        return result
      } else if (char === '\\') {
        i++
        if (i >= str.length) {
          this.error('unterminated string')
        }
        const nextChar = str[i]
        if (nextChar === 'n') {
          result += '\n'
        } else if (nextChar === 't') {
          result += '\t'
        } else if (nextChar === 'r') {
          result += '\r'
        } else if (nextChar === '\\') {
          result += '\\'
        } else if (nextChar === '"') {
          result += '"'
        } else if (nextChar === '0') {
          result += '\0'
        } else if (nextChar === 'u') {
          i++
          if (i + 3 >= str.length) {
            this.error('invalid escape \\u')
          }
          const hex = str.substr(i, 4)
          if (!/^[0-9a-fA-F]{4}$/.test(hex)) {
            this.error('invalid escape \\u')
          }
          result += String.fromCharCode(parseInt(hex, 16))
          i += 3
        } else {
          this.error(`invalid escape \\${nextChar}`)
        }
        i++
      } else {
        result += char
        i++
      }
    }

    this.error('unterminated string')
  }

  parseLiteralString(str) {
    if (!str.startsWith("'")) {
      this.error('expected a string')
    }

    let i = 1
    while (i < str.length) {
      if (str[i] === "'") {
        const rest = str.substring(i + 1)
        if (!this.isEndOfValue(rest)) {
          this.error('trailing text after a value')
        }
        return str.substring(1, i)
      }
      i++
    }

    this.error('unterminated string')
  }

  parseArray(str) {
    if (!str.startsWith('[')) {
      this.error('expected an array')
    }

    const result = []
    let i = 1
    let depth = 1

    while (i < str.length && depth > 0) {
      // Skip whitespace and comments
      while (i < str.length && /[\s\n\r\t]/.test(str[i])) {
        i++
      }

      if (i >= str.length) {
        this.error('unterminated array')
      }

      if (str[i] === '#' || str[i] === ';') {
        // Skip comment
        while (i < str.length && str[i] !== '\n' && str[i] !== '\r') {
          i++
        }
        continue
      }

      if (str[i] === ']') {
        depth--
        if (depth === 0) {
          i++
          const rest = str.substring(i)
          if (!this.isEndOfValue(rest)) {
            this.error('trailing text after a value')
          }
          return result
        }
        i++
        continue
      }

      if (str[i] === ',') {
        i++
        continue
      }

      // Parse a value
      let valStr = ''
      let stringDepth = 0
      let inString = false
      let stringChar = ''
      const startI = i

      while (i < str.length) {
        const char = str[i]

        if (!inString) {
          if (char === '"' || char === "'") {
            inString = true
            stringChar = char
            valStr += char
            i++
          } else if (char === '[') {
            valStr += char
            i++
            stringDepth++
          } else if (char === ']') {
            if (stringDepth === 0) {
              break
            }
            valStr += char
            i++
            stringDepth--
          } else if (char === '{') {
            valStr += char
            i++
            stringDepth++
          } else if (char === '}') {
            if (stringDepth === 0) {
              break
            }
            valStr += char
            i++
            stringDepth--
          } else if (char === ',') {
            break
          } else if (char === '#' || char === ';') {
            break
          } else {
            valStr += char
            i++
          }
        } else {
          if (char === stringChar && (stringChar === "'" || str[i - 1] !== '\\')) {
            inString = false
          } else if (char === '\\' && stringChar === '"') {
            valStr += char
            i++
            if (i < str.length) {
              valStr += str[i]
              i++
            }
            continue
          }
          valStr += char
          i++
        }
      }

      if (valStr.trim() !== '') {
        result.push(this.parseValue(valStr))
      }
    }

    this.error('unterminated array')
  }

  parseInlineTable(str) {
    if (!str.startsWith('{')) {
      this.error('expected an inline table')
    }

    const result = {}
    let i = 1

    while (i < str.length) {
      // Skip whitespace
      while (i < str.length && /[\s\t]/.test(str[i])) {
        i++
      }

      if (i >= str.length) {
        this.error('unterminated inline table')
      }

      if (str[i] === '}') {
        i++
        const rest = str.substring(i)
        if (!this.isEndOfValue(rest)) {
          this.error('trailing text after a value')
        }
        return result
      }

      if (str[i] === ',') {
        this.error('expected key = value')
      }

      // Parse key
      let keyStr = ''
      const keyStart = i

      if (str[i] === '"' || str[i] === "'") {
        const quote = str[i]
        i++
        while (i < str.length) {
          if (str[i] === quote) {
            i++
            keyStr = str.substring(keyStart + 1, i - 1)
            if (quote === '"') {
              // Decode escapes
              keyStr = this.decodeBasicString(keyStr)
            }
            break
          } else if (quote === '"' && str[i] === '\\') {
            i++
            if (i >= str.length) {
              this.error('unterminated string')
            }
            i++
          } else {
            i++
          }
        }
        if (keyStr === '') {
          this.error('expected a name')
        }
      } else {
        while (i < str.length && /[A-Za-z0-9_-]/.test(str[i])) {
          keyStr += str[i]
          i++
        }
        if (keyStr === '') {
          this.error('expected a name')
        }
      }

      // Skip whitespace
      while (i < str.length && /[\s\t]/.test(str[i])) {
        i++
      }

      // Expect =
      if (i >= str.length || str[i] !== '=') {
        this.error('expected = in an inline table')
      }
      i++

      // Skip whitespace
      while (i < str.length && /[\s\t]/.test(str[i])) {
        i++
      }

      // Parse value
      let valStr = ''
      let stringDepth = 0
      let inString = false
      let stringChar = ''

      while (i < str.length) {
        const char = str[i]

        if (!inString) {
          if (char === '"' || char === "'") {
            inString = true
            stringChar = char
            valStr += char
            i++
          } else if (char === '[') {
            valStr += char
            i++
            stringDepth++
          } else if (char === ']') {
            if (stringDepth === 0) {
              break
            }
            valStr += char
            i++
            stringDepth--
          } else if (char === '{') {
            valStr += char
            i++
            stringDepth++
          } else if (char === '}') {
            if (stringDepth === 0) {
              break
            }
            valStr += char
            i++
            stringDepth--
          } else if (char === ',') {
            break
          } else {
            valStr += char
            i++
          }
        } else {
          if (char === stringChar && (stringChar === "'" || str[i - 1] !== '\\')) {
            inString = false
          } else if (char === '\\' && stringChar === '"') {
            valStr += char
            i++
            if (i < str.length) {
              valStr += str[i]
              i++
            }
            continue
          }
          valStr += char
          i++
        }
      }

      if (valStr.trim() === '') {
        this.error('expected a value')
      }

      result[keyStr] = this.parseValue(valStr)

      // Skip whitespace
      while (i < str.length && /[\s\t]/.test(str[i])) {
        i++
      }

      if (i < str.length && str[i] === ',') {
        i++
      } else if (i < str.length && str[i] === '}') {
        // Next iteration will handle closing
      } else if (i >= str.length) {
        this.error('unterminated inline table')
      }
    }

    this.error('unterminated inline table')
  }

  decodeBasicString(str) {
    let result = ''
    let i = 0
    while (i < str.length) {
      if (str[i] === '\\') {
        i++
        if (i >= str.length) {
          return result
        }
        const char = str[i]
        if (char === 'n') result += '\n'
        else if (char === 't') result += '\t'
        else if (char === 'r') result += '\r'
        else if (char === '\\') result += '\\'
        else if (char === '"') result += '"'
        else if (char === '0') result += '\0'
        else if (char === 'u') {
          i++
          if (i + 3 < str.length) {
            const hex = str.substr(i, 4)
            if (/^[0-9a-fA-F]{4}$/.test(hex)) {
              result += String.fromCharCode(parseInt(hex, 16))
              i += 3
            }
          }
        }
        i++
      } else {
        result += str[i]
        i++
      }
    }
    return result
  }
}

function parseToml(input, mode) {
  const parser = new Parser(input)
  const doc = parser.parse()

  // Remove internal _defined markers
  removeMarkers(doc)

  return doc
}

function removeMarkers(obj) {
  if (typeof obj === 'object' && obj !== null) {
    delete obj._defined
    for (const key in obj) {
      removeMarkers(obj[key])
    }
  }
}

function toJSON(obj) {
  const json = JSON.stringify(obj, null, 2)
  return json
}

function toKeys(obj, prefix = '') {
  const lines = []
  const keys = Object.keys(obj).sort()

  for (const key of keys) {
    const value = obj[key]
    const path = prefix ? `${prefix}.${key}` : key
    const type = getType(value)

    lines.push(`${path} ${type}`)

    if (Array.isArray(value)) {
      // Array of tables
      for (let i = 0; i < value.length; i++) {
        const item = value[i]
        const itemPath = `${path}[${i}]`
        walkObject(item, itemPath, lines)
      }
    } else if (typeof value === 'object' && value !== null) {
      walkObject(value, path, lines)
    }
  }

  return lines.join('\n') + (lines.length > 0 ? '\n' : '')
}

function walkObject(obj, prefix, lines) {
  const keys = Object.keys(obj).sort()
  for (const key of keys) {
    const value = obj[key]
    const path = `${prefix}.${key}`
    const type = getType(value)

    lines.push(`${path} ${type}`)

    if (Array.isArray(value)) {
      for (let i = 0; i < value.length; i++) {
        const item = value[i]
        const itemPath = `${path}[${i}]`
        walkObject(item, itemPath, lines)
      }
    } else if (typeof value === 'object' && value !== null) {
      walkObject(value, path, lines)
    }
  }
}

function getType(value) {
