// Tokenizer/Parser
class Parser {
  constructor(input) {
    this.input = input
    this.pos = 0
    this.line = 1
    this.lines = input.split('\n').slice(0, -1) // Remove empty tail from trailing newline
    this.currentTable = null
    this.root = {}
  }

  error(msg) {
    throw new Error(`error: line ${this.line}: ${msg}`)
  }

  parse() {
    this.currentTable = this.root

    for (let i = 0; i < this.lines.length; i++) {
      this.line = i + 1
      const line = this.lines[i]
      const trimmed = line.trimStart()

      // Skip empty lines and comments
      if (trimmed === '' || trimmed[0] === '#' || trimmed[0] === ';') {
        continue
      }

      // Header line
      if (trimmed[0] === '[') {
        if (trimmed[1] === '[') {
          // Array of tables: [[name]]
          const match = trimmed.match(/^\[\[([^\]]*)\]\](.*)$/)
          if (!match) {
            this.error('unterminated table header')
          }
          const nameStr = match[1].trim()
          const trailing = match[2]
          if (!/^\s*(#|;|$)/.test(trailing)) {
            this.error('trailing text after a table header')
          }
          const name = this.parseDottedName(nameStr)
          this.handleArrayTableHeader(name)
        } else {
          // Regular table: [name]
          const match = trimmed.match(/^\[([^\]]*)\](.*)$/)
          if (!match) {
            this.error('unterminated table header')
          }
          const nameStr = match[1].trim()
          const trailing = match[2]
          if (!/^\s*(#|;|$)/.test(trailing)) {
            this.error('trailing text after a table header')
          }
          const name = this.parseDottedName(nameStr)
          this.handleTableHeader(name)
        }
      } else {
        // Key-value pair
        this.parseKeyValue(trimmed)
      }
    }

    return this.root
  }

  parseDottedName(str) {
    if (str === '') {
      this.error('expected a name')
    }
    const parts = []
    let pos = 0
    while (pos < str.length) {
      // Skip whitespace
      while (pos < str.length && (str[pos] === ' ' || str[pos] === '\t')) {
        pos++
      }
      if (pos >= str.length) break

      // Parse name
      let name
      if (str[pos] === '"' || str[pos] === "'") {
        const quote = str[pos]
        pos++
        let name_str = ''
        while (pos < str.length) {
          if (str[pos] === quote) {
            pos++
            name = name_str
            break
          } else if (quote === '"' && str[pos] === '\\') {
            pos++
            if (pos >= str.length) {
              this.error('unterminated string')
            }
            const char = str[pos]
            if (char === 'n') name_str += '\n'
            else if (char === 't') name_str += '\t'
            else if (char === 'r') name_str += '\r'
            else if (char === '\\') name_str += '\\'
            else if (char === '"') name_str += '"'
            else if (char === '0') name_str += '\0'
            else if (char === 'u') {
              pos++
              if (pos + 3 >= str.length) {
                this.error('invalid escape \\u')
              }
              const hex = str.substr(pos, 4)
              if (!/^[0-9a-fA-F]{4}$/.test(hex)) {
                this.error('invalid escape \\u')
              }
              name_str += String.fromCharCode(parseInt(hex, 16))
              pos += 3
            } else {
              this.error(`invalid escape \\${char}`)
            }
            pos++
          } else {
            name_str += str[pos]
            pos++
          }
        }
        if (name === undefined) {
          this.error('unterminated string')
        }
      } else {
        let name_str = ''
        while (pos < str.length && /[A-Za-z0-9_-]/.test(str[pos])) {
          name_str += str[pos]
          pos++
        }
        if (name_str === '') {
          this.error('expected a name')
        }
        name = name_str
      }
      parts.push(name)

      // Skip whitespace
      while (pos < str.length && (str[pos] === ' ' || str[pos] === '\t')) {
        pos++
      }

      // Check for dot
      if (pos < str.length && str[pos] === '.') {
