      const key = name[i]
      path.push(key)
      const pathStr = path.join('.')

      if (table[key] === undefined) {
        table[key] = {}
      } else if (typeof table[key] === 'object' && !Array.isArray(table[key])) {
        table = table[key]
        continue
      } else {
        this.error(`${pathStr} is not a table`)
      }

      table = table[key]
    }

    const lastKey = name[name.length - 1]
    path.push(lastKey)

    if (table[lastKey] === undefined) {
      table[lastKey] = []
    } else if (!Array.isArray(table[lastKey])) {
      this.error(`${path.join('.')} is not an array of tables`)
