export class ConfError extends Error {
  constructor(line, reason) {
    super(`line ${line}: ${reason}`)
    this.line = line
    this.reason = reason
  }
}

const BARE = /[A-Za-z0-9_-]/
const INT = /^[+-]?[0-9]+(_[0-9]+)*$/
const FLOAT =
  /^[+-]?[0-9]+(_[0-9]+)*(\.[0-9]+(_[0-9]+)*)?([eE][+-]?[0-9]+(_[0-9]+)*)?$/

function newTable() {
  return { kind: 'table', map: new Map(), header: false }
}

/** Renders a path of segments, a key or an array index, as text. */
export function renderPath(segments) {
  let out = ''
  let started = false
  for (const segment of segments) {
    if (segment.index !== undefined) {
      out += `[${segment.index}]`
    } else {
      out += started ? `.${segment.key}` : segment.key
      started = true
    }
  }
  return out
}

/** One line of the document, scanned left to right. */
class Line {
  constructor(text, number) {
    this.s = text
    this.n = text.length
    this.i = 0
    this.line = number
  }

  fail(reason) {
    throw new ConfError(this.line, reason)
  }

  /** Skips spaces and tabs. */
  space() {
    while (this.i < this.n && (this.s[this.i] === ' ' || this.s[this.i] === '\t')) this.i++
  }

  /** True at the end of the line, where a comment also ends it. */
  done() {
    return this.i >= this.n || this.s[this.i] === '#' || this.s[this.i] === ';'
  }

  at() {
    return this.i < this.n ? this.s[this.i] : ''
  }

  basicString() {
    this.i++
    let out = ''
    for (;;) {
      if (this.i >= this.n) this.fail('unterminated string')
      const c = this.s[this.i]
