/** Walks the dots of a name, creating the tables on the way. */
function walk(line, table, path, keys) {
  let cur = table
  for (let j = 0; j < keys.length - 1; j++) {
    const key = keys[j]
    path.push({ key })
    const held = cur.map.get(key)
    if (held === undefined) {
      const made = newTable()
      cur.map.set(key, made)
      cur = made
    } else if (held.kind === 'table') {
      cur = held
    } else if (held.kind === 'array' && held.aot && held.items.length > 0) {
      path.push({ index: held.items.length - 1 })
      cur = held.items[held.items.length - 1]
    } else {
