/** Assigns a value at a dotted name inside a table. */
function assign(line, table, basePath, keys, value) {
  const path = basePath.slice()
  const cur = walk(line, table, path, keys)
  const key = keys[keys.length - 1]
  path.push({ key })
  if (cur.map.has(key)) line.fail(`key ${renderPath(path)} is defined twice`)
  cur.map.set(key, value)
}

/** Parses a whole document and answers its root table. */
export function parse(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const root = newTable()
  let current = root
  let currentPath = []

