      const array = line.s[line.i + 1] === '['
      line.i += array ? 2 : 1
      line.space()
      const keys = line.dottedName()
      line.space()
      if (array) {
        if (line.at() !== ']' || line.s[line.i + 1] !== ']') line.fail('unterminated table header')
        line.i += 2
      } else {
        if (line.at() !== ']') line.fail('unterminated table header')
        line.i += 1
      }
      line.space()
      if (!line.done()) line.fail('trailing text after a table header')

      const path = []
      const parent = walk(line, root, path, keys)
      const key = keys[keys.length - 1]
      path.push({ key })
      const held = parent.map.get(key)
      if (array) {
        let holder = held
        if (holder === undefined) {
          holder = { kind: 'array', items: [], aot: true }
          parent.map.set(key, holder)
        } else if (!(holder.kind === 'array' && holder.aot)) {
          line.fail(`${renderPath(path)} is not an array of tables`)
        }
        const made = newTable()
        made.header = true
        holder.items.push(made)
        path.push({ index: holder.items.length - 1 })
        current = made
        currentPath = path
      } else {
        let table = held
        if (table === undefined) {
          table = newTable()
          parent.map.set(key, table)
        } else if (table.kind !== 'table') {
          line.fail(`${renderPath(path)} is not a table`)
        } else if (table.header) {
          line.fail(`table ${renderPath(path)} is defined twice`)
        }
        table.header = true
        current = table
        currentPath = path
      }
      continue
    }

    const keys = line.dottedName()
    line.space()
    if (line.at() !== '=') line.fail('expected key = value')
    line.i++
    const value = line.value(currentPath.concat(keys.map((key) => ({ key }))))
    line.space()
    if (!line.done()) line.fail('trailing text after a value')
    assign(line, current, currentPath, keys, value)
  }

  return root
}
