/** Compares two keys by code point. */
function byCodePoint(a, b) {
  const left = Array.from(a)
  const right = Array.from(b)
  const n = Math.min(left.length, right.length)
  for (let i = 0; i < n; i++) {
    const x = left[i].codePointAt(0)
    const y = right[i].codePointAt(0)
    if (x !== y) return x < y ? -1 : 1
  }
  return left.length - right.length
}

function sortedKeys(table) {
  return Array.from(table.map.keys()).sort(byCodePoint)
}

function jsonOf(node, depth) {
  if (node.kind === 'table') {
    const keys = sortedKeys(node)
    if (keys.length === 0) return '{}'
    const inner = '  '.repeat(depth + 1)
    const outer = '  '.repeat(depth)
    const members = keys.map(
      (key) => `${inner}${JSON.stringify(key)}: ${jsonOf(node.map.get(key), depth + 1)}`
    )
    return `{\n${members.join(',\n')}\n${outer}}`
  }
  if (node.kind === 'array') {
    if (node.items.length === 0) return '[]'
    const inner = '  '.repeat(depth + 1)
    const outer = '  '.repeat(depth)
    const items = node.items.map((item) => inner + jsonOf(item, depth + 1))
    return `[\n${items.join(',\n')}\n${outer}]`
  }
  if (node.kind === 'string') return JSON.stringify(node.value)
  if (node.kind === 'boolean') return node.value ? 'true' : 'false'
  return String(node.value)
}

export function toJson(root) {
  return jsonOf(root, 0) + '\n'
}

function walkKeys(node, path, out) {
  if (node.kind === 'table') {
    for (const key of sortedKeys(node)) {
      const child = node.map.get(key)
      const childPath = path === '' ? key : `${path}.${key}`
      out.push(`${childPath} ${child.kind}\n`)
      walkKeys(child, childPath, out)
    }
  } else if (node.kind === 'array') {
    node.items.forEach((item, index) => {
      const childPath = `${path}[${index}]`
      out.push(`${childPath} ${item.kind}\n`)
      walkKeys(item, childPath, out)
    })
  }
}

export function toKeys(root) {
  const out = []
  walkKeys(root, '', out)
  return out.join('')
}
