              i += 3
            }
          }
        }
        i++
      } else {
        result += str[i]
        i++
      }
    }
    return result
  }
}

function parseToml(input, mode) {
  const parser = new Parser(input)
  const doc = parser.parse()

  // Remove internal _defined markers
  removeMarkers(doc)

  return doc
}

function removeMarkers(obj) {
  if (typeof obj === 'object' && obj !== null) {
    delete obj._defined
    for (const key in obj) {
      removeMarkers(obj[key])
    }
  }
}

function toJSON(obj) {
  return stringifyJSON(obj, 0)
}

function stringifyJSON(obj, depth) {
  if (obj === null) {
    return 'null'
  }
  if (typeof obj === 'boolean') {
    return obj ? 'true' : 'false'
  }
  if (typeof obj === 'number') {
    return String(obj)
  }
  if (typeof obj === 'string') {
    return JSON.stringify(obj)
  }
  if (Array.isArray(obj)) {
    if (obj.length === 0) {
      return '[]'
    }
    const indent = '  '.repeat(depth + 1)
    const closing = '  '.repeat(depth)
    const items = obj.map(item => indent + stringifyJSON(item, depth + 1))
    return '[\n' + items.join(',\n') + '\n' + closing + ']'
  }
  if (typeof obj === 'object') {
    const keys = Object.keys(obj).sort()
    if (keys.length === 0) {
      return '{}'
    }
    const indent = '  '.repeat(depth + 1)
    const closing = '  '.repeat(depth)
    const pairs = keys.map(key => {
      const value = stringifyJSON(obj[key], depth + 1)
      return indent + JSON.stringify(key) + ': ' + value
    })
    return '{\n' + pairs.join(',\n') + '\n' + closing + '}'
  }
  return 'null'
}

function toKeys(obj, prefix = '') {
  const lines = []
  const keys = Object.keys(obj).sort()

  for (const key of keys) {
    const value = obj[key]
    const path = prefix ? `${prefix}.${key}` : key
    const type = getType(value)

    lines.push(`${path} ${type}`)

    if (Array.isArray(value)) {
      // Array of tables
      for (let i = 0; i < value.length; i++) {
        const item = value[i]
        const itemPath = `${path}[${i}]`
        walkObject(item, itemPath, lines)
      }
    } else if (typeof value === 'object' && value !== null) {
      walkObject(value, path, lines)
    }
  }

  return lines.join('\n') + (lines.length > 0 ? '\n' : '')
}

function walkObject(obj, prefix, lines) {
  const keys = Object.keys(obj).sort()
  for (const key of keys) {
    const value = obj[key]
    const path = `${prefix}.${key}`
    const type = getType(value)

    lines.push(`${path} ${type}`)

    if (Array.isArray(value)) {
      for (let i = 0; i < value.length; i++) {
        const item = value[i]
        const itemPath = `${path}[${i}]`
        walkObject(item, itemPath, lines)
      }
    } else if (typeof value === 'object' && value !== null) {
      walkObject(value, path, lines)
    }
  }
}

function getType(value) {
  if (typeof value === 'boolean') {
    return 'boolean'
  } else if (typeof value === 'number') {
    return Number.isInteger(value) ? 'integer' : 'float'
  } else if (typeof value === 'string') {
    return 'string'
  } else if (Array.isArray(value)) {
    // Check if it's an array of tables (all elements are objects)
    if (value.length > 0 && typeof value[0] === 'object' && !Array.isArray(value[0])) {
      return 'array'
    }
    return 'array'
  } else if (typeof value === 'object') {
    return 'table'
  }
  return 'unknown'
}

