import { readFileSync } from 'node:fs'
import { ConfError, parse } from './parse.js'
import { toJson, toKeys } from './render.js'

function main(argv) {
  const mode = argv[0]
  if (argv.length !== 1 || (mode !== 'json' && mode !== 'keys')) {
    process.stderr.write('error: usage: cli.js json|keys\n')
    return 2
  }

  let input = ''
  try {
    input = readFileSync(0, 'utf8')
  } catch {
    input = ''
  }

  let out
  try {
    const root = parse(input)
    out = mode === 'json' ? toJson(root) : toKeys(root)
  } catch (error) {
    if (error instanceof ConfError) {
      process.stderr.write(`error: ${error.message}\n`)
      return 2
    }
    throw error
  }

  process.stdout.write(out)
  return 0
}

process.exitCode = main(process.argv.slice(2))

